CREATE TABLE v161112 (v161113 BIGINT PRIMARY KEY) AS SELECT EXTRACTVALUE(@xml, '/a/b[@c="c" or @c="d"]'), INET_NTOA(0), ST_DISTANCE(ST_GEOMFROMTEXT(365), ST_GEOMFROMTEXT('LINESTRING(0 0, 50 45, 40 50, 0 0)')), BIN_TO_UUID(UUID_TO_BIN(BIN_TO_UUID(x2, TRUE), TRUE), TRUE), SEC_TO_TIME('$b*<*#]E'), ADDDATE(CAST('x' AS DOUBLE), INTERVAL '1' DAY), EXTRACTVALUE('POINT(163 130)', '::0x1.2.3.4')